const Cart=function(){function storageKey(storeSlug){return"skiri_cart_"+storeSlug}function getCart(storeSlug){try{return JSON.parse(localStorage.getItem(storageKey(storeSlug)))||[]}catch(err){return[]}}function saveCart(storeSlug,cart){localStorage.setItem(storageKey(storeSlug),JSON.stringify(cart))}function minQtyOf(line){const n=Number(line&&line.minQty);return n>1&&Math.floor(n)===n?n:1}function unitPriceOf(line){const base=Math.round(Number(line.unitPrice)*100)/100;let price=base;(Array.isArray(line.tiers)?line.tiers:[]).forEach(t=>{if(t&&Number(line.qty)>=Number(t.minQty)&&Number(t.price)>0)price=Math.round(Number(t.price)*100)/100});return Math.min(price,base)}function lineTotal(line){return Math.round(unitPriceOf(line)*line.qty*100)/100}function nextTierOf(line){const tiers=Array.isArray(line.tiers)?line.tiers:[];return tiers.find(t=>t&&Number(t.minQty)>Number(line.qty)&&Number(t.price)<unitPriceOf(line))||null}function addItem(storeSlug,item){const cart=getCart(storeSlug);const existing=cart.find(line=>line.variantId===item.variantId);if(existing){existing.qty+=item.qty;if(item.imageUrl&&!existing.imageUrl)existing.imageUrl=item.imageUrl;if(item.tiers!==undefined||item.minQty!==undefined){existing.tiers=item.tiers;existing.minQty=item.minQty;existing.unitPrice=item.unitPrice}existing.qty=Math.max(existing.qty,minQtyOf(existing))}else{cart.push(Object.assign({},item,{qty:Math.max(item.qty,minQtyOf(item))}))}saveCart(storeSlug,cart);return cart}function updateQty(storeSlug,variantId,qty){let cart=getCart(storeSlug);if(qty<=0){cart=cart.filter(line=>line.variantId!==variantId)}else{cart.forEach(line=>{if(line.variantId===variantId)line.qty=Math.max(qty,minQtyOf(line))})}saveCart(storeSlug,cart);return cart}function removeItem(storeSlug,variantId){return updateQty(storeSlug,variantId,0)}function clearCart(storeSlug){saveCart(storeSlug,[])}function getTotal(storeSlug){return getCart(storeSlug).reduce((sum,line)=>sum+lineTotal(line),0)}function getItemCount(storeSlug){return getCart(storeSlug).reduce((sum,line)=>sum+line.qty,0)}function getDistinctProductCount(storeSlug){const ids={};getCart(storeSlug).forEach(line=>{ids[line.productId]=true});return Object.keys(ids).length}function photoFor(product,variantId){const v=(product.variants||[]).filter(x=>x.variantId===variantId)[0];if(v&&Array.isArray(v.images)&&v.images[0])return v.images[0];const own=typeof productOwnPhotos==="function"?productOwnPhotos(product):[product.imageUrl];return own[0]||""}const photoLookups={};function fillPhotos(storeSlug){const missing=getCart(storeSlug).filter(l=>!l.imageUrl&&!l.noPhoto);if(!missing.length||typeof Api==="undefined")return Promise.resolve(false);if(!photoLookups[storeSlug]){photoLookups[storeSlug]=Api.get("listProducts",{storeSlug:storeSlug}).then(res=>res&&res.ok?res.products||[]:null).catch(()=>null)}return photoLookups[storeSlug].then(products=>{if(!products)return false;const cart=getCart(storeSlug);let changed=false;cart.forEach(line=>{if(line.imageUrl||line.noPhoto)return;const p=products.filter(x=>x.productId===line.productId)[0];const url=p?photoFor(p,line.variantId):"";if(url)line.imageUrl=url;else line.noPhoto=true;changed=true});if(changed)saveCart(storeSlug,cart);return changed})}function thumbHtml(line,cls){const c="cart-thumb"+(cls?" "+cls:"");if(line.imageUrl){const src=typeof optimizedImageUrl==="function"?optimizedImageUrl(line.imageUrl,IMG_W.thumb):line.imageUrl;return`<img class="${c}" src="${escapeHtml(src)}" alt="" loading="lazy" decoding="async">`}const name=String(line.label||"").split(" — ")[0];return`<span class="${c} cart-thumb--empty" aria-hidden="true">${escapeHtml(typeof initials==="function"?initials(name):name.charAt(0))}</span>`}return{getCart:getCart,addItem:addItem,updateQty:updateQty,removeItem:removeItem,clearCart:clearCart,getTotal:getTotal,getItemCount:getItemCount,getDistinctProductCount:getDistinctProductCount,unitPriceOf:unitPriceOf,lineTotal:lineTotal,minQtyOf:minQtyOf,nextTierOf:nextTierOf,photoFor:photoFor,fillPhotos:fillPhotos,thumbHtml:thumbHtml}}();